    if len(T) != 87:
        raise ValueError("Sequence T does not have 87 elements.")
    if T[0] != 0 or T[-1] != 171:
        raise ValueError("Sequence boundaries are incorrect.")

    # Calculate the sum set S = {t_i + t_j | 0 <= i <= j <= 86}
    sum_set = set()
    for i in range(len(T)):
        for j in range(i, len(T)):
            sum_set.add(T[i] + T[j])

    return len(sum_set)

